-- Original educational samples, clearly separate from automatically discovered news.
do $$
declare item jsonb; word jsonb; question jsonb; article_id uuid; question_id uuid; q_order integer;
begin
  for item in select value from jsonb_array_elements($data$
  [
    {"slug":"technology-changing-education","title":"How Technology Is Changing Education","summary":"An original beginner reading about useful classroom technology.","category":"Education","stage":"foundation","passage":"Mia goes to school every day. Her class has books, pencils, and a large screen. The teacher shows a picture of the moon on the screen. Mia likes the picture. She can see mountains and dark spaces on the moon. After class, Mia uses a tablet to read a short story. She also writes three new words in her notebook. The tablet is helpful, but Mia still talks with her teacher and friends. They ask questions and learn together. Technology gives Mia new ways to see and read. People help her understand what she learns.","words":[["tablet","máy tính bảng","a small portable computer"],["picture","bức tranh","an image"],["notebook","sổ tay","a book for writing notes"],["helpful","hữu ích","giving help"]],"questions":[["multiple_choice","What does the teacher show?",["A picture of the moon","A picture of a car","A video of the sea"],"A picture of the moon","The teacher shows a picture of the moon."],["true_false_not_given","Mia reads a story on a tablet.",["True","False","Not Given"],"True","The passage says Mia uses a tablet to read a short story."],["vocabulary","What does helpful mean?",["Giving help","Very old","Hard to use"],"Giving help","The tablet gives Mia another way to read."],["main_idea","What is the main idea?",["Technology and people can help learning","Students do not need teachers","The moon is close to Earth"],"Technology and people can help learning","The final lines combine technology with people."],["short_answer","Where does Mia write new words?",[],"in her notebook","The passage says she writes them in her notebook."]] },
    {"slug":"why-reading-every-day-matters","title":"Why Reading Every Day Matters","summary":"A short original story about building a reading habit.","category":"Culture","stage":"elementary","passage":"Leo wanted to read more English, but long books felt difficult. He decided to read for ten minutes after breakfast. On Monday, he read a short story about a garden. He did not know every word, so he wrote only the most useful words in a notebook. On Tuesday, he read the story again and understood more. By Friday, reading felt easier. Leo then chose a new story about the sea. He learned that a small daily habit could change his confidence. Reading did not become easy in one day. It became easier because he returned to it again and again.","words":[["habit","thói quen","something you do regularly"],["confidence","sự tự tin","belief in your ability"],["useful","hữu ích","helpful for a purpose"],["understood","đã hiểu","knew the meaning"]],"questions":[["multiple_choice","When did Leo read?",["After breakfast","Before dinner","At midnight"],"After breakfast","He read for ten minutes after breakfast."],["true_false_not_given","Leo wrote every unknown word.",["True","False","Not Given"],"False","He wrote only the most useful words."],["vocabulary","What is a habit?",["Something done regularly","A type of book","A place to read"],"Something done regularly","His regular ten-minute reading is a habit."],["main_idea","What helped Leo improve?",["Reading a little each day","Buying many books","Stopping when a word was hard"],"Reading a little each day","The passage emphasizes a small daily habit."],["short_answer","What was Leo's first story about?",[],"a garden","The first story was about a garden."]] },
    {"slug":"how-cities-can-become-greener","title":"How Cities Can Become Greener","summary":"Explore practical ways to make urban places healthier.","category":"Environment","stage":"pre-ielts","passage":"Many cities have busy roads and tall buildings, but they can also make room for nature. A group of neighbors in one city changed an empty lot into a small garden. They planted trees, flowers, and vegetables. The trees gave shade on hot days, while the flowers attracted insects that help plants grow. The garden also became a place where people could meet. Other residents asked the city for safer paths so they could walk or cycle instead of driving short distances. These changes did not solve every environmental problem. However, they made the neighborhood more pleasant and showed that small local projects can encourage wider action.","words":[["shade","bóng râm","a cooler area protected from sunlight"],["residents","cư dân","people who live in a place"],["neighborhood","khu phố","an area where people live"],["encourage","khuyến khích","to make someone more willing to act"]],"questions":[["multiple_choice","What was the empty lot changed into?",["A garden","A car park","A factory"],"A garden","Neighbors made a small garden."],["true_false_not_given","The garden solved every environmental problem.",["True","False","Not Given"],"False","The passage says the changes did not solve every problem."],["vocabulary","What does shade mean here?",["A cool area away from direct sun","A type of insect","A city road"],"A cool area away from direct sun","Trees gave shade on hot days."],["main_idea","What is the passage mainly about?",["Small local actions can improve cities","All cities must remove roads","Gardens are only for vegetables"],"Small local actions can improve cities","The garden and paths are examples of local action."],["short_answer","How could residents travel short distances instead of driving?",[],"walk or cycle","The passage mentions walking or cycling."]] },
    {"slug":"future-of-renewable-energy","title":"The Future of Renewable Energy","summary":"An original explainer about wind, solar power, and storage.","category":"Science","stage":"ielts-starter","passage":"Solar panels and wind turbines can produce electricity without burning fossil fuels. Their output, however, changes with the weather. On a cloudy afternoon, solar panels generate less power, and a calm day may leave wind turbines still. Energy storage helps bridge this gap. Batteries can save electricity when production is high and release it later when demand rises. Some communities also share power across a wider network, allowing one area to help another. Building this system requires careful planning and investment. It also requires people to use energy efficiently. Renewable energy is therefore more than a set of machines: it is a way to organize production, storage, and everyday demand together.","words":[["turbine","tuabin","a machine turned by wind or water"],["generate","tạo ra","to produce"],["storage","lưu trữ","keeping something for later use"],["demand","nhu cầu","the amount people need"]],"questions":[["multiple_choice","Why is storage useful?",["It saves power for later","It makes clouds disappear","It stops people using energy"],"It saves power for later","Batteries save electricity and release it later."],["true_false_not_given","Solar output never changes.",["True","False","Not Given"],"False","Solar output changes with weather."],["vocabulary","What does generate mean?",["Produce","Hide","Measure"],"Produce","The panels generate power."],["main_idea","What is central to renewable energy systems?",["Coordinating production, storage, and demand","Using only wind turbines","Avoiding all investment"],"Coordinating production, storage, and demand","The final sentence names these parts."],["short_answer","What can batteries release when demand rises?",[],"electricity","Batteries release electricity later."]] },
    {"slug":"exercise-supports-mental-focus","title":"Why Exercise Supports Mental Focus","summary":"A balanced original reading about movement and concentration.","category":"Health","stage":"ielts-builder","passage":"A short walk does not replace sleep, healthy food, or medical care, but it can help many people reset their attention. When a student spends a long time on one task, small distractions may become more noticeable. Taking a break to move can create a clear boundary between periods of work. The change of scenery may also help the student return with a fresh perspective. Researchers continue to study how different forms of movement affect cognition, and the results vary between people. For this reason, it is better to view exercise as one useful part of a wider routine than as a guaranteed way to improve every mental task. The most sustainable plan is often a simple activity that a person enjoys enough to repeat.","words":[["attention","sự chú ý","the ability to focus"],["boundary","ranh giới","a dividing line"],["cognition","nhận thức","mental processes for thinking and learning"],["sustainable","bền vững","possible to continue over time"]],"questions":[["multiple_choice","What can a movement break create?",["A boundary between work periods","A substitute for sleep","A guaranteed cure"],"A boundary between work periods","The passage directly describes a clear boundary."],["true_false_not_given","Every person responds to movement in exactly the same way.",["True","False","Not Given"],"False","Results vary between people."],["vocabulary","What does sustainable mean in this context?",["Easy to continue over time","Very expensive","Related to the weather"],"Easy to continue over time","The person enjoys repeating the activity."],["main_idea","What is the writer's position?",["Movement can support focus as part of a wider routine","Exercise guarantees perfect concentration","Students should never take breaks"],"Movement can support focus as part of a wider routine","The passage avoids a guarantee and favors a routine."],["short_answer","What type of activity may be easiest to repeat?",[],"a simple activity a person enjoys","The final sentence recommends an enjoyable simple activity."]] },
    {"slug":"ocean-data-and-climate","title":"How Ocean Data Helps Us Understand Climate","summary":"Read about measurements, trends, and uncertainty.","category":"Science","stage":"ielts-advanced","passage":"The ocean absorbs much of the excess heat trapped by greenhouse gases, yet measuring change across such a vast system is difficult. Scientists combine observations from ships, floating instruments, satellites, and coastal stations. Each source reveals a different part of the picture and carries its own limitations. A satellite can survey a large area quickly, for example, while an instrument below the surface can reveal conditions that a satellite cannot observe directly. Researchers compare measurements across many years to identify long-term patterns rather than treating one unusual season as a permanent trend. They also report uncertainty, because gaps in coverage and differences between instruments affect estimates. This careful approach makes the evidence more useful for decisions about coastal planning and climate adaptation.","words":[["absorb","hấp thụ","to take in"],["limitations","giới hạn","factors that restrict usefulness"],["uncertainty","độ không chắc chắn","limits to confidence in an estimate"],["adaptation","sự thích ứng","adjusting to changing conditions"]],"questions":[["multiple_choice","Why combine different observation sources?",["Each reveals different information","Satellites record everything","Ships cannot measure water"],"Each reveals different information","The passage says each source offers a different part of the picture."],["true_false_not_given","One unusual season proves a permanent climate trend.",["True","False","Not Given"],"False","Researchers compare many years instead."],["vocabulary","What does uncertainty refer to?",["Limits to confidence in estimates","A new type of satellite","A coastal station"],"Limits to confidence in estimates","Coverage gaps and instrument differences affect estimates."],["main_idea","What is the main argument?",["Careful, combined measurements improve understanding","Only satellites should be used","Climate data has no use for planning"],"Careful, combined measurements improve understanding","The passage connects complementary methods to useful evidence."],["short_answer","Name one decision area this evidence can support.",[],"coastal planning","The final sentence names coastal planning."]] },
    {"slug":"sustainable-transport-choices","title":"The Trade-offs Behind Sustainable Transport","summary":"An advanced original discussion of access, emissions, and public policy.","category":"Environment","stage":"mastery","passage":"Transport policy is often described as a choice between private cars and public transit, but the real decisions are more complex. A new rail line may lower emissions per passenger while providing little benefit to people whose homes are far from stations. Electric buses can reduce street-level pollution, yet their impact also depends on how electricity is generated and how frequently buses run. Walking and cycling infrastructure can improve local access, provided routes are safe and connected. A fair transition therefore requires planners to examine both environmental outcomes and who can actually use the service. Evidence should include travel times, cost, reliability, and accessibility for people with different needs. No single mode offers a universal solution; effective networks combine several options and adapt them to local conditions.","words":[["emissions","khí thải","gases released into the air"],["infrastructure","cơ sở hạ tầng","basic facilities that support a system"],["accessibility","khả năng tiếp cận","how easily people can use something"],["transition","quá trình chuyển đổi","a change from one system to another"]],"questions":[["multiple_choice","Why might a rail line offer limited benefit?",["Some homes are far from stations","Trains never lower emissions","Passengers dislike stations"],"Some homes are far from stations","Distance from stations can limit access."],["true_false_not_given","Electric buses always have the same environmental impact.",["True","False","Not Given"],"False","Impact depends partly on electricity and service frequency."],["vocabulary","What does accessibility mean here?",["Ease of using a service","The size of a vehicle","The price of electricity"],"Ease of using a service","The passage considers people with different needs."],["main_idea","What should transport planners consider?",["Environmental outcomes and usable access","Only the number of vehicles","One universal mode for every place"],"Environmental outcomes and usable access","The passage explicitly combines these goals."],["short_answer","Name one measure of service quality mentioned.",[],"reliability","The evidence list includes reliability."]] }
  ]$data$::jsonb)
  loop
    insert into public.news_learning_articles(slug,title,summary,category,stage_id,passage,rights_status,rights_basis,published)
    values(item->>'slug',item->>'title',item->>'summary',item->>'category',item->>'stage',item->>'passage','ORIGINAL','Original educational writing created for English Skill Lab; no third-party article text.',false)
    returning id into article_id;
    for word in select value from jsonb_array_elements(item->'words') loop
      insert into public.news_vocabulary(article_id,word,meaning_vi,definition)
      values(article_id,word->>0,word->>1,word->>2);
    end loop;
    q_order := 0;
    for question in select value from jsonb_array_elements(item->'questions') loop
      insert into public.news_questions(article_id,kind,prompt,options,sort_order)
      values(article_id,question->>0,question->>1,question->2,q_order)
      returning id into question_id;
      insert into public.news_answer_keys(question_id,correct_answer,explanation)
      values(question_id,question->>3,question->>4);
      q_order := q_order + 1;
    end loop;
    update public.news_learning_articles set published=true where id=article_id;
  end loop;
end;
$$;
